# server-start.ps1 - start Mainframe server only
# AUTO-GENERATED by Tools/gen_launchers.py. Do not edit by hand.
# Regenerate: python Tools/gen_launchers.py
$ErrorActionPreference = "Continue"
$Root = Split-Path -Parent $PSScriptRoot
$CfgFile = Join-Path $Root "config.json"
if (-not (Test-Path $CfgFile)) { Write-Host "config.json not found: $CfgFile" -ForegroundColor Red; exit 1 }
$Cfg = Get-Content $CfgFile -Raw | ConvertFrom-Json
$env:JEWAI_CONFIG = $CfgFile
function Log($m) { Write-Host ("[" + (Get-Date -Format "HH:mm:ss") + "] " + $m) }

Set-Location $Root
$port = 8670
$busy = $false
try { $busy = (Test-NetConnection -ComputerName 127.0.0.1 -Port $port -InformationLevel Quiet -WarningAction SilentlyContinue) } catch {}
if ($busy) { Log "mainframe already on $port"; exit 0 }
Start-Process pythonw -ArgumentList @("Mainframe\server.py") -WorkingDirectory $Root -WindowStyle Hidden
Log "mainframe starting on $port"
